<?php
require_once 'auth.php'; requireAdmin();
if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['claim_id'], $_POST['decision'])) {
    requireCsrf();
    $decision = $_POST['decision']; $claimId = filter_input(INPUT_POST, 'claim_id', FILTER_VALIDATE_INT);
    if ($claimId && in_array($decision, ['approved', 'rejected'], true)) db()->prepare('UPDATE claims SET status = ?, admin_note = ? WHERE id = ?')->execute([$decision, trim($_POST['admin_note'] ?? ''), $claimId]);
    header('Location: admin.php?claim_updated=1'); exit;
}
$counts = db()->query("SELECT COUNT(*) total, SUM(status = 'open') open_items, SUM(status = 'returned') returned_items FROM items")->fetch(PDO::FETCH_ASSOC);
$pendingClaims = db()->query("SELECT COUNT(*) FROM claims WHERE status = 'pending'")->fetchColumn();
$items = db()->query('SELECT items.*, users.name AS account_name FROM items LEFT JOIN users ON users.id = items.user_id ORDER BY created_at DESC')->fetchAll(PDO::FETCH_ASSOC);
$claims = db()->query("SELECT claims.*, items.title AS item_title, users.name AS claimant_name, users.email AS claimant_email FROM claims JOIN items ON items.id = claims.item_id JOIN users ON users.id = claims.user_id ORDER BY claims.created_at DESC")->fetchAll(PDO::FETCH_ASSOC);
$pageTitle = 'Admin Dashboard'; require 'header.php';
?>
<section class="page-heading"><div><p class="eyebrow">Administrator</p><h1>Dashboard</h1><p class="intro">Manage all community item reports.</p></div></section>
<?php if (isset($_GET['deleted'])): ?><div class="alert success">The report was deleted.</div><?php endif; ?><?php if (isset($_GET['claim_updated'])): ?><div class="alert success">Claim decision saved.</div><?php endif; ?>
<section class="stats"><div><strong><?= $counts['total'] ?></strong><span>Total reports</span></div><div><strong><?= $counts['open_items'] ?></strong><span>Open items</span></div><div><strong><?= $counts['returned_items'] ?></strong><span>Returned items</span></div><div><strong><?= $pendingClaims ?></strong><span>Pending claims</span></div></section>
<section class="admin-table"><h2>Claim requests</h2><div class="table-wrap"><table><thead><tr><th>Item</th><th>Claimant</th><th>Proof</th><th>Status</th><th>Review</th></tr></thead><tbody><?php foreach ($claims as $claim): ?><tr><td><strong><?= htmlspecialchars($claim['item_title']) ?></strong></td><td><?= htmlspecialchars($claim['claimant_name']) ?><small><?= htmlspecialchars($claim['claimant_email']) ?></small></td><td><?= htmlspecialchars($claim['message']) ?></td><td><span class="status <?= $claim['status'] === 'pending' ? 'pending' : $claim['status'] ?>"><?= ucfirst($claim['status']) ?></span></td><td><?php if ($claim['status'] === 'pending'): ?><form class="review-form" method="post"><?= csrfInput() ?><input type="hidden" name="claim_id" value="<?= $claim['id'] ?>"><input name="admin_note" placeholder="Optional note"><button name="decision" value="approved" class="approve" type="submit">Approve</button><button name="decision" value="rejected" class="reject" type="submit">Reject</button></form><?php endif; ?></td></tr><?php endforeach; ?><?php if (!$claims): ?><tr><td colspan="5" class="muted">No claim requests yet.</td></tr><?php endif; ?></tbody></table></div></section>
<section class="admin-table"><h2>All item reports</h2><div class="table-wrap"><table><thead><tr><th>Item</th><th>Type</th><th>Location</th><th>Reporter</th><th>Status</th><th>Manage</th></tr></thead><tbody><?php foreach ($items as $item): ?><tr><td><strong><?= htmlspecialchars($item['title']) ?></strong><small><?= htmlspecialchars($item['category']) ?></small></td><td><span class="badge <?= $item['item_type'] ?>"><?= ucfirst($item['item_type']) ?></span></td><td><?= htmlspecialchars($item['location']) ?></td><td><?= htmlspecialchars($item['account_name'] ?: $item['contact_name']) ?></td><td><span class="status <?= $item['status'] ?>"><?= ucfirst($item['status']) ?></span></td><td><a href="item.php?id=<?= $item['id'] ?>">View</a><form class="inline-delete" method="post" action="delete_item.php" onsubmit="return confirm('Delete this report?')"><?= csrfInput() ?><input type="hidden" name="id" value="<?= $item['id'] ?>"><button type="submit">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></div></section>
<?php require 'footer.php'; ?>
